#!/usr/bin/env bash
# L1 (deterministic) harness for PR #6286 — exercises the PR's own shell code:
#   * test/gha-e2e/mooncake/test.sh :: check_runtime_config_injection /
#     check_missing_dataset_rejected (against a stub kubectl)
#   * test/gha-e2e/mooncake/image/custom-entrypoint.sh worker branch
#     (against the runtime.sh generated by the real Go code, plus fixtures)
#   * the rendered rw_job.yaml container script (syntax)
# All tests are CONTRACT polarity: they assert the intended correct behavior.
set -uo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$HERE/../../../.." && pwd)"
FIXTURES="$HERE/fixtures"
RESULTS="$HERE/../results"
mkdir -p "$RESULTS"
LOG="$RESULTS/shell-harness.log"
: > "$LOG"

pass=0; fail=0
ok()   { pass=$((pass+1)); echo "PASS: $1" | tee -a "$LOG"; }
bad()  { fail=$((fail+1)); echo "FAIL: $1" | tee -a "$LOG"; }

# --- helpers ---------------------------------------------------------------

# test.sh ends by invoking main; strip everything from "function main()" on so
# the real function definitions (and top-level globals) can be sourced.
STRIPPED_TESTSH="$RESULTS/test.functions-only.sh"
sed '/^function main()/,$d' "$REPO_ROOT/test/gha-e2e/mooncake/test.sh" > "$STRIPPED_TESTSH"

# Runs one scenario of a test.sh function in a subshell with a stub kubectl.
# $1 = function name, $2 = stub kubectl body. Prints subshell output; rc = subshell rc.
run_testsh_scenario() {
  local fn="$1" stub="$2"
  local stubdir; stubdir=$(mktemp -d)
  printf '#!/bin/bash\n%s\n' "$stub" > "$stubdir/kubectl"
  chmod +x "$stubdir/kubectl"
  ( PATH="$stubdir:$PATH"; source "$STRIPPED_TESTSH"; "$fn" )
  local rc=$?
  rm -rf "$stubdir"
  return $rc
}

# --- A. syntax --------------------------------------------------------------

bash -n "$REPO_ROOT/test/gha-e2e/mooncake/image/custom-entrypoint.sh" 2>>"$LOG" \
  && ok "A1 bash -n custom-entrypoint.sh" || bad "A bash -n custom-entrypoint.sh"
bash -n "$REPO_ROOT/test/gha-e2e/mooncake/test.sh" 2>>"$LOG" \
  && ok "A bash -n test.sh" || bad "A bash -n test.sh"
sh -n "$FIXTURES/rw_job_rendered.sh" 2>>"$LOG" \
  && ok "A sh -n rendered rw_job script (dash-compatible)" || bad "A sh -n rendered rw_job script"

# --- B/C/D/E. custom-entrypoint.sh worker branch ----------------------------

ENTRYPOINT="$REPO_ROOT/test/gha-e2e/mooncake/image/custom-entrypoint.sh"
RUNTIME_SH="$RESULTS/runtime.sh.generated"
[ -f "$RUNTIME_SH" ] || RUNTIME_SH="$FIXTURES/runtime.sh.generated"

run_entrypoint() { # $1 = config dir
  local cfgdir="$1" stubdir; stubdir=$(mktemp -d)
  printf '#!/bin/bash\necho "MOONCAKE_CLIENT_ARGS:"\nprintf "  %%s\n" "$@"\n' > "$stubdir/mooncake_client"
  chmod +x "$stubdir/mooncake_client"
  PATH="$stubdir:$PATH" \
  FLUID_RUNTIME_CONFIG_PATH="$cfgdir/runtime.json" \
  FLUID_DATASET_NAMESPACE=default \
  POD_NAME=mooncake-demo-worker-0 \
    bash "$ENTRYPOINT" worker start 2>&1
  local rc=$?
  rm -rf "$stubdir"
  return $rc
}

mkcfgdir() { # $1 = dir name (may contain spaces); creates runtime.json+runtime.sh
  local d="$RESULTS/$1"; mkdir -p "$d"
  echo '{}' > "$d/runtime.json"
  cp "$RUNTIME_SH" "$d/runtime.sh"
  echo "$d"
}

out=$(run_entrypoint "$(mkcfgdir cfg-happy)"); rc=$?
echo "$out" >> "$LOG"
exp_master="--master_server_address=svc-mooncake-demo-master.default.svc.cluster.local:50051"
exp_meta="--metadata_server=http://svc-mooncake-demo-master.default.svc.cluster.local:8080/metadata"
exp_host="--host=mooncake-demo-worker-0.svc-mooncake-demo-worker.default.svc.cluster.local"
exp_seg="--global_segment_size=1GB"
if [ $rc -eq 0 ] && grep -qF -- "$exp_master" <<<"$out" && grep -qF -- "$exp_meta" <<<"$out" \
   && grep -qF -- "$exp_host" <<<"$out" && grep -qF -- "$exp_seg" <<<"$out"; then
  ok "B worker entrypoint: runtime.sh drives master/metadata/host/segment args"
else
  bad "B worker entrypoint happy path (rc=$rc): $out"
fi

out=$(PATH="$PATH" FLUID_DATASET_NAMESPACE=default POD_NAME=p bash -c 'unset FLUID_RUNTIME_CONFIG_PATH; exec bash "'"$ENTRYPOINT"'" worker start' 2>&1); rc=$?
echo "$out" >> "$LOG"
if [ $rc -ne 0 ] && grep -q "missing runtime config path" <<<"$out"; then
  ok "C worker entrypoint: unset FLUID_RUNTIME_CONFIG_PATH aborts immediately"
else
  bad "C worker entrypoint with unset config path (rc=$rc): $out"
fi

out=$(run_entrypoint "$(mkcfgdir 'cfg with spaces')"); rc=$?
echo "$out" >> "$LOG"
if [ $rc -eq 0 ] && grep -qF -- "$exp_master" <<<"$out"; then
  ok "D worker entrypoint: config path containing spaces loads fine"
else
  bad "D worker entrypoint with spaces in path (rc=$rc): $out"
fi

d="$RESULTS/cfg-missing-sh"; mkdir -p "$d"; echo '{}' > "$d/runtime.json"
out=$(run_entrypoint "$d"); rc=$?
echo "$out" >> "$LOG"
if [ $rc -ne 0 ]; then
  ok "E worker entrypoint: missing runtime.sh aborts (set -e), message: $(tail -1 <<<"$out")"
else
  bad "E worker entrypoint silently continued without runtime.sh: $out"
fi

# --- F. check_runtime_config_injection against the #6197-shaped pod ---------

F1() { run_testsh_scenario check_runtime_config_injection "cat '$1'"; }

if out=$(F1 "$FIXTURES/pod-injected.json"); then
  ok "F1 injection check passes for the webhook-shaped injected pod"
else
  bad "F1 injection check REJECTED the expected injected pod: $out"
fi

mktemp_variant() { # $1 = jq mutation
  local f; f=$(mktemp --suffix=.json)
  jq "$1" "$FIXTURES/pod-injected.json" > "$f"; echo "$f"
}

v=$(mktemp_variant '.items[0].spec.containers[0].volumeMounts[0].readOnly = false')
out=$(F1 "$v") && bad "F2 filter accepted a WRITABLE config mount" || ok "F2 filter rejects a writable config mount"

v=$(mktemp_variant '.items[0].spec.containers[0].env[1].name = "FLUID_RUNTIME_CONFIG_PATH_MOONCAKEDEMO"')
out=$(F1 "$v") && bad "F3 filter accepted a wrong env var name" || ok "F3 filter rejects a wrong env var name"

v=$(mktemp_variant '.items[0].spec.containers[0].env[1].value = "/etc/fluid/config/mooncake-demo/runtime.json"')
out=$(F1 "$v") && bad "F4 filter accepted env pointing at runtime.json" || ok "F4 filter rejects env pointing at runtime.json"

v=$(mktemp_variant '.items[0].spec.volumes = []')
out=$(F1 "$v") && bad "F5 filter accepted a pod with no config volume" || ok "F5 filter rejects a pod with no config volume"

v=$(mktemp_variant '.items = []')
out=$(F1 "$v") && bad "F6 filter accepted an empty pod list" || ok "F6 filter rejects an empty pod list (no succeeded pod)"

# --- G. check_missing_dataset_rejected --------------------------------------

DENIAL='Error from server: admission webhook "clientless.fluid.io" denied the request: failed to collect runtime infos from annotation fluid.io/datasets: failed to get the following datasets [mooncake-missing] declared in annotation fluid.io/datasets: mooncake-missing: datasets.data.fluid.io "mooncake-missing" not found'

out=$(run_testsh_scenario check_missing_dataset_rejected "echo '$DENIAL' >&2; exit 1"); rc=$?
echo "$out" >> "$LOG"
if [ $rc -eq 0 ]; then
  ok "G1 rejection check passes on the real denial shape (webhook + dataset name)"
else
  bad "G1 rejection check failed on the expected denial: $out"
fi

out=$(run_testsh_scenario check_missing_dataset_rejected "echo 'pod/mooncake-rejection-check created (server dry run)'; exit 0"); rc=$?
echo "$out" >> "$LOG"
if [ $rc -ne 0 ] && grep -q "expected admission to reject" <<<"$out"; then
  ok "G2 rejection check panics when admission ALLOWS the missing dataset (today's master / CI failure)"
else
  bad "G2 rejection check did not panic on admission-allowed (rc=$rc): $out"
fi

out=$(run_testsh_scenario check_missing_dataset_rejected "echo 'Error from server: failed calling webhook: connection refused' >&2; exit 1"); rc=$?
echo "$out" >> "$LOG"
if [ $rc -ne 0 ] && grep -q "unexpected admission error" <<<"$out"; then
  ok "G3 rejection check panics on an unrelated webhook error"
else
  bad "G3 rejection check mishandled an unrelated error (rc=$rc): $out"
fi

echo "----- shell harness: $pass passed, $fail failed -----" | tee -a "$LOG"
[ $fail -eq 0 ]
